/bin/bash -lc "cat > /tmp/check-drip.cjs <<'EOF'
const fs = require('fs');
const vm = require('vm');
const assert = require('assert/strict');
const code = fs.readFileSync('/tmp/drip-script.js', 'utf8');
const store = new Map();
function boot() {
  const nodes = new Map(), events = {};
  const get = key => {
    if ("'!nodes.has(key)) nodes.set(key, {textContent:'"'', innerHTML:'', style:{}, attrs:{}, handlers:{}, open:false, value:'', classList:{add(){},remove(){},toggle(){}},setAttribute(k,v){this.attrs[k]=v},addEventListener(k,v){this.handlers[k]=v},showModal(){this.open=true},close(){this.open=false}});
    return nodes.get(key);
  };
  const sizes=[150,250,500].map(n=>{let el=get('amount'+n);el.dataset={amount:String(n)};return el});
  const context={document:{querySelector:get,querySelectorAll:()=>sizes,addEventListener:(k,f)=>events[k]=f},localStorage:{getItem:k=>store.get(k),setItem:(k,v)=>store.set(k,v)},window:{scrollTo(){}},setTimeout:()=>1,clearTimeout(){},setInterval(){},Date,Math,Number,JSON};
  vm.runInNewContext(code,context);
  const click=(selector,node)=>events.click({target:{closest:s=>s===selector?node:null}});
  return {get,events,click,sizes};
}
let app=boot();
assert.equal(app.get('#total-amount').textContent,'1,250');
app.get('#log-water').handlers.click();
assert.equal(app.get('#total-amount').textContent,'1,500');
app.get('#undo-button').handlers.click();
assert.equal(app.get('#total-amount').textContent,'1,250');
app.click('[data-amount]',app.sizes[2]);
app.get('#log-water').handlers.click();
assert.equal(app.get('#total-amount').textContent,'1,750');
app.get('#goal-input').value='2500';
app.get('#modal-content').handlers.submit({preventDefault(){},target:{id:'goal-form'}});
assert.equal(app.get('#goal-label').textContent,'Goal: 2,500 ml');
assert.equal(app.get('#percentage').textContent,'70% of daily goal');
app.get('#custom-input').value='375';
app.get('#modal-content').handlers.submit({preventDefault(){},target:{id:'custom-form'}});
assert.equal(app.get('#total-amount').textContent,'2,125');
app=boot();
assert.equal(app.get('#total-amount').textContent,'2,125');
assert.equal(app.get('#goal-label').textContent,'Goal: 2,500 ml');
app.click('[data-open]',{dataset:{open:'history'}});
assert.equal(app.get('#modal').open,true);
assert.ok(app.get('#modal-content').innerHTML.includes('2,125 ml in 6 sips'));
app.get('#close-modal').handlers.click();
assert.equal(app.get('#modal').open,false);
console.log('Passed: initial progress, quick log, undo, size selection, goal editing, custom logging, persistence, history dialog.');
EOF
node /tmp/check-drip.cjs"

